import json

import requests
from requests.auth import HTTPBasicAuth
from six import raise_from

try:
    from urllib.parse import urlparse
except ImportError:
    from urlparse import urlparse


class ClientRegistrationFailed(Exception):
    pass


class AlreadyRegistered(Exception):
    pass


class ClientRegistration(object):

    @staticmethod
    def select_registration_endpoint(apigw_uri):
        """
        Since NOM22 release the usage of subdomains, like `apigw`, is abandoned
        and the registration endpoint name is changed.
        """
        if urlparse(apigw_uri).netloc.lower().startswith('apigw.'):
            return 'auth/api/v1/apps/registrations'
        else:
            return 'authz/api/v1/apps/registrations'

    @staticmethod
    def register_client(client_id, username, password, apigw_uri):
        try:
            response = ClientRegistration._get_client_registration_response(client_id=client_id,
                                                                            username=username,
                                                                            password=password,
                                                                            apigw_uri=apigw_uri
                                                                            )
            return response["clientSecret"]
        except Exception as e:
            raise_from(ClientRegistrationFailed(), e)

    @staticmethod
    def _get_client_registration_response(client_id, username, password, apigw_uri):
        # authentication failure will result in 404
        client_token_endpoint = "{apigw_uri}/{registration_endpoint}".format(
            apigw_uri=apigw_uri, registration_endpoint=ClientRegistration.select_registration_endpoint(apigw_uri)
        )
        headers = {"Content-Type": "application/json"}

        body = json.dumps({"clientId": client_id})

        response = requests.post(
            client_token_endpoint, headers=headers, data=body, verify=False, auth=HTTPBasicAuth(username, password)
        )

        if response.status_code == 409:
            raise AlreadyRegistered()
        else:
            response.raise_for_status()

        return response.json()

    @staticmethod
    def delete_client(client_id, username, password, apigw_uri):
        client_token_endpoint = "{apigw_uri}/{registration_endpoint}/{client_id}".format(
            apigw_uri=apigw_uri, registration_endpoint=ClientRegistration.select_registration_endpoint(apigw_uri),
            client_id=client_id
        )
        headers = {"Content-Type": "application/json"}

        response = requests.delete(
            client_token_endpoint, headers=headers, verify=False, auth=HTTPBasicAuth(username, password)
        )

        response.raise_for_status()

        return response.json()
